1	"use client";
2	
3	/**
4	 * PREVIEW TEMPLATE — "AI / vibe-coding hosting".
5	 *
6	 * The most modern page on the site: a Claude-powered "Build with AI" builder
7	 * that also hosts. The hero centerpiece is a genuinely-animated
8	 * describe → build → deploy → live flow (a chat prompt types, Claude streams
9	 * build steps that check off, a deploy terminal resolves to "Live in 47s", and
10	 * a light browser frame assembles the built site). A second wedge lets you
11	 * import an app you already vibe-coded elsewhere (Bolt / Lovable / v0 / Cursor)
12	 * and host it. Asymmetric, editorial, motion-forward — never a centered stack.
13	 *
14	 * Net-new, preview-only. Touches no live page or shared component.
15	 */
16	
17	import Link from "next/link";
18	import { useEffect, useRef, useState } from "react";
19	import styles from "./aihosting.module.css";
20	import { usePrefersReducedMotion, useInViewOnce, StarRow, LiveDot } from "./kit";
21	import { ReasonIcon } from "./icons-map";
22	import {
23	  BUILD_PROMPT,
24	  BUILD_STEPS,
25	  DEPLOY_STEPS,
26	  IMPORT_SOURCES,
27	  REASONS,
28	  PLANS,
29	  REVIEWS,
30	  RATING_AVG,
31	  RATING_LABEL,
32	} from "./data";
33	import { ClaudeMark } from "@/components/marketing/ClaudeMark";
34	import { IconCheck, IconArrow, IconBolt } from "@/components/marketing/icons";
35	
36	/* ── Hero centerpiece: describe → build → deploy → live ──────────────────── */
37	function BuildConsole() {
38	  const reduced = usePrefersReducedMotion();
39	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
40	  const [typed, setTyped] = useState("");
41	  const [phase, setPhase] = useState<"idle" | "typing" | "building" | "deploying" | "live">("idle");
42	  const [built, setBuilt] = useState(0);
43	  const [deployed, setDeployed] = useState(0);
44	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
45	
46	  useEffect(() => {
47	    if (!seen) return;
48	    if (reduced) {
49	      setTyped(BUILD_PROMPT);
50	      setBuilt(BUILD_STEPS.length);
51	      setDeployed(DEPLOY_STEPS.length);
52	      setPhase("live");
53	      return;
54	    }
55	    let dead = false;
56	    const push = (fn: () => void, ms: number) => {
57	      if (!dead) timers.current.push(setTimeout(fn, ms));
58	    };
59	    const run = () => {
60	      setTyped("");
61	      setBuilt(0);
62	      setDeployed(0);
63	      setPhase("typing");
64	      const charMs = 34;
65	      BUILD_PROMPT.split("").forEach((_, i) => push(() => setTyped(BUILD_PROMPT.slice(0, i + 1)), 300 + charMs * i));
66	      const afterType = 300 + charMs * BUILD_PROMPT.length + 500;
67	      push(() => setPhase("building"), afterType);
68	      BUILD_STEPS.forEach((_, i) => push(() => setBuilt(i + 1), afterType + 720 * (i + 1)));
69	      const afterBuild = afterType + 720 * (BUILD_STEPS.length + 1);
70	      push(() => setPhase("deploying"), afterBuild);
71	      DEPLOY_STEPS.forEach((_, i) => push(() => setDeployed(i + 1), afterBuild + 640 * (i + 1)));
72	      const afterDeploy = afterBuild + 640 * (DEPLOY_STEPS.length + 1);
73	      push(() => setPhase("live"), afterDeploy);
74	      push(run, afterDeploy + 5200); // loop
75	    };
76	    run();
77	    return () => {
78	      dead = true;
79	      timers.current.forEach(clearTimeout);
80	      timers.current = [];
81	    };
82	  }, [seen, reduced]);
83	
84	  const showSite = phase === "live";
85	
86	  return (
87	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
88	      <div className="relative grid gap-4 sm:grid-cols-[1.05fr_0.95fr] sm:items-start">
89	        {/* ambient glow behind the console */}
90	        <div
91	          className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
92	          style={{
93	            background:
94	              "radial-gradient(45% 45% at 15% 0%, rgba(59,130,246,0.22), transparent 70%), radial-gradient(45% 50% at 95% 100%, rgba(138,112,251,0.24), transparent 70%)",
95	          }}
96	          aria-hidden
97	        />
98	
99	        {/* Claude chat / build panel */}
100	        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
101	          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
102	            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
103	              <ClaudeMark size={13} />
104	            </span>
105	            <span className="text-[12px] font-medium text-slate-300">Claude · connected to your server</span>
106	            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
107	              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
108	              live
109	            </span>
110	          </div>
111	
112	          <div className="space-y-3 px-4 py-4 text-[13px] leading-relaxed">
113	            {/* user prompt (typing) */}
114	            <div className="ml-auto max-w-[88%] rounded-2xl rounded-br-sm border border-brand-500/25 bg-brand-500/10 px-3.5 py-2.5 text-slate-100">
115	              {typed || <span className="text-slate-500">Describe what you want to build…</span>}
116	              {phase === "typing" && (
117	                <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-brand-300 motion-safe:animate-blink" />
118	              )}
119	            </div>
120	
121	            {/* claude building */}
122	            {(phase === "building" || phase === "deploying" || phase === "live") && (
123	              <div className="max-w-[94%] rounded-2xl rounded-bl-sm border border-white/[0.07] bg-white/[0.03] px-3.5 py-3">
124	                <p className="text-slate-300">On it — here&apos;s the plan:</p>
125	                <ul className="mt-2.5 space-y-1.5 font-mono text-[12px]">
126	                  {BUILD_STEPS.map((s, i) => {
127	                    const done = built > i;
128	                    return (
129	                      <li key={s.label} className={`flex items-center gap-2 ${done ? "text-slate-300" : "text-slate-600"}`}>
130	                        <span
131	                          className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full ${
132	                            done ? "bg-emerald-500/15 text-emerald-400" : "border border-white/10 text-transparent"
133	                          }`}
134	                        >
135	                          <IconCheck size={10} />
136	                        </span>
137	                        <span className="flex-1">{s.label}</span>
138	                        <span className="text-slate-600">{s.detail}</span>
139	                      </li>
140	                    );
141	                  })}
142	                </ul>
143	
144	                {/* review-before-ship gate (honesty) */}
145	                {(phase === "deploying" || phase === "live") && (
146	                  <div className="mt-3 flex items-center gap-2 rounded-lg border border-brand-500/25 bg-brand-500/[0.08] px-2.5 py-1.5 text-[11px] text-brand-200">
147	                    <IconCheck size={12} />
148	                    You reviewed the plan and approved it
149	                  </div>
150	                )}
151	
152	                {/* deploy stream */}
153	                {(phase === "deploying" || phase === "live") && (
154	                  <div className="mt-2.5 space-y-0.5 font-mono text-[11.5px]">
155	                    {DEPLOY_STEPS.slice(0, deployed).map((l, i) => {
156	                      const ok = l.startsWith("✓");
157	                      return (
158	                        <div key={i} className={ok ? "font-semibold text-emerald-300" : "text-slate-400"}>
159	                          {l}
160	                        </div>
161	                      );
162	                    })}
163	                  </div>
164	                )}
165	              </div>
166	            )}
167	          </div>
168	
169	          <div className="border-t border-white/[0.06] px-4 py-3">
170	            <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-[12px] text-slate-500">
171	              Ask Claude to build or change anything
172	              <span className="inline-block h-3.5 w-1.5 bg-slate-500 motion-safe:animate-blink" />
173	              <span className="ml-auto flex h-6 w-6 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-white">
174	                <ClaudeMark size={12} />
175	              </span>
176	            </div>
177	          </div>
178	        </div>
179	
180	        {/* result: assembling browser preview (light, for contrast pop) */}
181	        <div className="relative">
182	          <div className="overflow-hidden rounded-2xl border border-white/10 bg-white shadow-2xl shadow-black/40">
183	            <div className="flex items-center gap-2 border-b border-black/10 bg-slate-100 px-3 py-2">
184	              <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
185	              <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
186	              <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
187	              <span className="ml-2 flex-1 truncate rounded-md bg-white px-2.5 py-1 text-[10px] text-slate-500 ring-1 ring-black/5">
188	                {showSite ? "https://lumen-salon.nxeon.app" : "building…"}
189	              </span>
190	            </div>
191	            <div className="relative min-h-[248px] bg-gradient-to-b from-[#faf7f2] to-white">
192	              {!showSite ? (
193	                <div className="flex min-h-[248px] flex-col items-center justify-center gap-3 px-6 text-center">
194	                  <span className="flex h-9 w-9 items-center justify-center rounded-full border-2 border-brand-500/30 border-t-brand-500 motion-safe:animate-orbit-spin" />
195	                  <p className="text-[12px] font-medium text-slate-400">Your site is assembling…</p>
196	                </div>
197	              ) : (
198	                <div className="px-4 py-3">
199	                  <div className={`flex items-center justify-between ${reduced ? "" : styles.rise}`} style={{ animationDelay: "0ms" }}>
200	                    <span className="text-[13px] font-bold tracking-tight text-emerald-800">Lumen Salon</span>
201	                    <div className="hidden gap-2 text-[9px] text-slate-500 sm:flex">
202	                      <span>Services</span>
203	                      <span>Gallery</span>
204	                      <span className="rounded-full bg-emerald-700 px-2 py-0.5 text-white">Book</span>
205	                    </div>
206	                  </div>
207	                  <div className={`mt-3 text-center ${reduced ? "" : styles.rise}`} style={{ animationDelay: "90ms" }}>
208	                    <p className="text-[9px] font-semibold uppercase tracking-[0.2em] text-emerald-700">Wellness &amp; calm</p>
209	                    <h4 className="mt-1 text-base font-bold leading-tight text-slate-800">
210	                      Relax, restore, <span className="text-emerald-700">renew.</span>
211	                    </h4>
212	                    <span className="mt-2 inline-block rounded-full bg-emerald-700 px-3 py-1 text-[10px] font-semibold text-white">
213	                      Book an appointment
214	                    </span>
215	                  </div>
216	                  <div className="mt-3 grid grid-cols-3 gap-2">
217	                    {["Massage", "Facials", "Sauna"].map((s, i) => (
218	                      <div
219	                        key={s}
220	                        className={`rounded-lg bg-white p-2 text-left shadow-sm ring-1 ring-black/5 ${reduced ? "" : styles.rise}`}
221	                        style={{ animationDelay: `${180 + i * 90}ms` }}
222	                      >
223	                        <div className="mb-1.5 h-6 rounded bg-emerald-100" />
224	                        <p className="text-[9px] font-semibold text-slate-700">{s}</p>
225	                        <p className="text-[8px] text-slate-400">from $60</p>
226	                      </div>
227	                    ))}
228	                  </div>
229	                </div>
230	              )}
231	            </div>
232	          </div>
233	          {/* live tag under the browser */}
234	          <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-[12px] text-slate-300 backdrop-blur-md">
235	            <LiveDot />
236	            {showSite ? (
237	              <>
238	                <span className="font-semibold text-accent-cyan">Live</span> · HTTPS issued · 47s from prompt
239	              </>
240	            ) : (
241	              <>Deploying to your server…</>
242	            )}
243	          </div>
244	        </div>
245	      </div>
246	    </div>
247	  );
248	}
249	
250	/* ── Import wedge terminal (auto-cycles through sources) ──────────────────── */
251	function ImportShowcase() {
252	  const reduced = usePrefersReducedMotion();
253	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
254	  const [active, setActive] = useState(0);
255	
256	  useEffect(() => {
257	    if (!seen || reduced) return;
258	    const id = window.setInterval(() => {
259	      if (document.hidden) return;
260	      setActive((a) => (a + 1) % IMPORT_SOURCES.length);
261	    }, 3400);
262	    return () => window.clearInterval(id);
263	  }, [seen, reduced]);
264	
265	  const src = IMPORT_SOURCES[active];
266	  const lines = [
267	    { t: `$ nxeon import ./my-app --from ${src.id}`, cls: "text-slate-200" },
268	    { t: `→ detected  ${src.detects}`, cls: "text-slate-400" },
269	    { t: "→ installing dependencies …… ok", cls: "text-slate-400" },
270	    { t: "→ building & issuing HTTPS …… ok", cls: "text-slate-400" },
271	    { t: "✓ deployed — my-app.nxeon.app", cls: "font-semibold text-emerald-300" },
272	  ];
273	
274	  return (
275	    <div ref={ref} className="grid gap-8 lg:grid-cols-2 lg:items-center lg:gap-12">
276	      {/* copy + source chips */}
277	      <div>
278	        <span className="eyebrow">Already built it elsewhere?</span>
279	        <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
280	          Import your <span className="grad-text">Bolt, Lovable, v0 or Cursor</span> app — and host it here
281	        </h2>
282	        <p className="mt-4 max-w-md text-lg leading-relaxed text-slate-400">
283	          Vibe-coded a prototype somewhere else? Bring the project over. We detect the framework, build it, and put it
284	          live on your own server — with full root and no lock-in.
285	        </p>
286	        <div className="mt-6 flex flex-wrap gap-2.5">
287	          {IMPORT_SOURCES.map((s, i) => (
288	            <button
289	              key={s.id}
290	              type="button"
291	              onClick={() => setActive(i)}
292	              aria-pressed={i === active}
293	              className={`inline-flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition-all ${
294	                i === active
295	                  ? "border-transparent bg-white/[0.06] text-white"
296	                  : "border-white/10 bg-white/[0.02] text-slate-400 hover:border-white/20 hover:text-slate-200"
297	              }`}
298	              style={i === active ? { boxShadow: `0 0 0 1px ${s.accent}66, 0 12px 30px -16px ${s.accent}` } : undefined}
299	            >
300	              <span
301	                className="flex h-5 w-5 items-center justify-center rounded-md text-[11px] font-bold"
302	                style={{ background: `${s.accent}22`, color: s.accent }}
303	                aria-hidden
304	              >
305	                {s.mark}
306	              </span>
307	              {s.name}
308	            </button>
309	          ))}
310	        </div>
311	        <Link href="/register" className="btn-primary mt-7 inline-flex px-6 py-3 text-base">
312	          Import a project
313	          <IconArrow size={16} />
314	        </Link>
315	      </div>
316	
317	      {/* terminal */}
318	      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-black/60 shadow-2xl backdrop-blur-sm">
319	        <div
320	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
321	          style={{ background: `radial-gradient(45% 45% at 85% 0%, ${src.accent}30, transparent 70%)` }}
322	          aria-hidden
323	        />
324	        <div className="flex items-center gap-1.5 border-b border-white/[0.06] px-4 py-2.5">
325	          <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
326	          <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
327	          <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
328	          <span className="ml-2 font-mono text-[11px] uppercase tracking-widest text-slate-500">nxeon · import</span>
329	          <span
330	            className="ml-auto inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 font-mono text-[10px]"
331	            style={{ borderColor: `${src.accent}55`, color: src.accent }}
332	          >
333	            from {src.name}
334	          </span>
335	        </div>
336	        {/* keyed on `active` so switching source replays the line-in reveal */}
337	        <div key={active} className="min-h-[168px] space-y-1.5 p-4 font-mono text-[12.5px] leading-relaxed">
338	          {lines.map((l, i) => (
339	            <div
340	              key={i}
341	              className={`${l.cls} ${reduced ? "" : "motion-safe:animate-line-in"}`}
342	              style={{ animationDelay: `${i * 260}ms` }}
343	            >
344	              {l.t}
345	            </div>
346	          ))}
347	        </div>
348	      </div>
349	    </div>
350	  );
351	}
352	
353	/* ── Stack ribbon (marquee of things you can build/host) ─────────────────── */
354	const STACK = [
355	  "Next.js",
356	  "React",
357	  "Vite",
358	  "Node",
359	  "Postgres",
360	  "Python",
361	  "Astro",
362	  "Express",
363	  "Prisma",
364	  "Tailwind",
365	  "SvelteKit",
366	  "Remix",
367	];
368	function StackRibbon() {
369	  return (
370	    <div className={`${styles.marquee} relative overflow-hidden`}>
371	      {/* edge fades */}
372	      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-24 bg-gradient-to-r from-navy-950 to-transparent" aria-hidden />
373	      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-navy-950 to-transparent" aria-hidden />
374	      <div className={styles.marqueeTrack} aria-hidden>
375	        {[...STACK, ...STACK].map((t, i) => (
376	          <span
377	            key={i}
378	            className="mx-1.5 shrink-0 rounded-full border border-white/[0.07] bg-white/[0.02] px-4 py-1.5 text-sm font-medium text-slate-400"
379	          >
380	            {t}
381	          </span>
382	        ))}
383	      </div>
384	    </div>
385	  );
386	}
387	
388	/* ── Reasons bento ───────────────────────────────────────────────────────── */
389	function ReasonCard({ r, featured = false, delay }: { r: (typeof REASONS)[number]; featured?: boolean; delay: number }) {
390	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
391	  return (
392	    <div
393	      ref={ref}
394	      className={`group relative flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md transition-all duration-700 ease-out hover:border-white/15 ${
395	        featured ? "h-full p-8" : "p-6"
396	      } ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
397	      style={{ transitionDelay: `${delay}ms` }}
398	    >
399	      {featured && (
400	        <div className="pointer-events-none absolute -right-10 -top-10 h-56 w-56 rounded-full bg-brand-500/12 opacity-70 blur-3xl" aria-hidden />
401	      )}
402	      <div className="flex items-center gap-3">
403	        <span className="flex items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300" style={{ width: featured ? 52 : 44, height: featured ? 52 : 44 }}>
404	          <ReasonIcon icon={r.icon} size={featured ? 26 : 20} />
405	        </span>
406	        <span className="font-mono text-sm text-slate-600">{r.n}</span>
407	      </div>
408	      <h3 className={`mt-5 font-semibold text-white ${featured ? "text-2xl sm:text-3xl" : "text-lg"}`}>{r.title}</h3>
409	      <p className={`mt-2 leading-relaxed text-slate-400 ${featured ? "text-base max-w-md" : "text-sm"}`}>{r.body}</p>
410	      {featured && (
411	        <div className="mt-auto pt-8">
412	          <div className="inline-flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5">
413	            <LiveDot />
414	            <span className="text-sm text-slate-300">
415	              Prompt to live: <span className="font-semibold text-accent-cyan">~47 seconds</span>
416	            </span>
417	          </div>
418	        </div>
419	      )}
420	    </div>
421	  );
422	}
423	
424	/* ── Main template ───────────────────────────────────────────────────────── */
425	export function AIHostingTemplate() {
426	  return (
427	    <div className="relative">
428	      {/* ── HERO ──────────────────────────────────────────────────────────── */}
429	      <section className="relative isolate overflow-hidden">
430	        {/* aurora backdrop */}
431	        <div className="pointer-events-none absolute inset-0 -z-10 overflow-hidden" aria-hidden>
432	          <div
433	            className={`absolute inset-x-0 -top-1/3 h-[90vh] ${styles.aurora}`}
434	            style={{
435	              background:
436	                "radial-gradient(45% 45% at 20% 20%, rgba(111,71,245,0.20), transparent 70%), radial-gradient(40% 45% at 80% 10%, rgba(34,211,238,0.14), transparent 70%), radial-gradient(45% 40% at 60% 60%, rgba(59,130,246,0.14), transparent 70%)",
437	            }}
438	          />
439	        </div>
440	
441	        <div className="rail grid items-center gap-12 py-20 lg:grid-cols-12 lg:gap-8 lg:py-24">
442	          <div className="lg:col-span-5">
443	            <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/10 px-3 py-1.5 text-xs font-semibold text-brand-200">
444	              <ClaudeMark size={14} />
445	              Build with Claude AI · then host it
446	            </span>
447	            <h1 className="mt-5 text-[2.6rem] font-bold leading-[1.04] tracking-tight text-white sm:text-6xl">
448	              Describe your idea. <span className="grad-text">It builds and ships itself.</span>
449	            </h1>
450	            <p className="mt-6 max-w-xl text-lg leading-relaxed text-slate-300/90">
451	              Tell Claude what you want in plain English — it scaffolds the app, builds it on a real server, and puts it
452	              online with HTTPS. Or bring an app you vibe-coded elsewhere and host it here.
453	            </p>
454	
455	            {/* speed hook */}
