1	/* Co-located CSS Module for the AI-hosting preview template. Scoped keyframes
2	   that the shipped design system doesn't already provide. Every animation is
3	   disabled under prefers-reduced-motion. Preview-only; never imported by a live
4	   page. */
5	
6	/* Continuous horizontal marquee (import-source / stack ribbon). The track is
7	   rendered twice back-to-back so a -50% translate loops seamlessly. */
8	.marqueeTrack {
9	  display: flex;
10	  width: max-content;
11	  animation: ai-marquee 26s linear infinite;
12	}
13	.marquee:hover .marqueeTrack {
14	  animation-play-state: paused;
15	}
16	@keyframes ai-marquee {
17	  from {
18	    transform: translateX(0);
19	  }
20	  to {
21	    transform: translateX(-50%);
22	  }
23	}
24	
25	/* Slow aurora drift for the hero backdrop — cheap opacity/transform only. */
26	.aurora {
27	  animation: ai-aurora 14s ease-in-out infinite alternate;
28	}
29	@keyframes ai-aurora {
30	  from {
31	    transform: translate3d(-2%, 0, 0) scale(1);
32	    opacity: 0.7;
33	  }
34	  to {
35	    transform: translate3d(3%, -2%, 0) scale(1.08);
36	    opacity: 1;
37	  }
38	}
39	
40	/* A soft rise-in used for the assembling browser preview blocks. */
41	.rise {
42	  opacity: 0;
43	  transform: translateY(10px);
44	  animation: ai-rise 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
45	}
46	@keyframes ai-rise {
47	  to {
48	    opacity: 1;
49	    transform: translateY(0);
50	  }
51	}
52	
53	@media (prefers-reduced-motion: reduce) {
54	  .marqueeTrack,
55	  .aurora,
56	  .rise {
57	    animation: none;
58	  }
59	  .rise {
60	    opacity: 1;
61	    transform: none;
62	  }
63	}
