1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { getSetting } from "@/lib/settings";
4	
5	/**
6	 * Third-party review badges (Trustpilot · HostAdvice · Google) for the hero.
7	 *
8	 * REAL DATA, WITH AN HONEST FALLBACK (2026-08-10). This component now reads the
9	 * live Reviews engine:
10	 *
11	 *   - It aggregates APPROVED reviews by external source (Google/Trustpilot/
12	 *     HostAdvice) into a real average score and count, and links each badge to
13	 *     the review-profile URL configured in /admin/reviews.
14	 *   - A source is only shown as a REAL badge when it has ≥1 approved review AND a
15	 *     configured profile URL — so we never render a live-looking badge that links
16	 *     nowhere or is backed by nothing.
17	 *   - When NO source qualifies (the normal pre-launch state), it falls back to the
18	 *     clearly-labelled DEMO PLACEHOLDER below, so the hero never looks empty.
19	 *
20	 * ⚠️ DEMO PLACEHOLDER — the scores/counts in `DEMO_BADGES` are NOT real review
21	 * data. They exist only so the hero has something to show before real reviews are
22	 * approved. They are never mixed with real data: the moment one real external
23	 * review exists, the whole strip switches to real badges only. Do not publish
24	 * these figures as genuine — collect real reviews (they'll appear automatically).
25	 */
26	
27	type Badge = { name: string; score: string; count: string; href: string; star: string; google?: boolean };
28	
29	const DEMO_BADGES: Badge[] = [
30	  { name: "Trustpilot", score: "4.9", count: "312", href: "#", star: "#00b67a" },
31	  { name: "HostAdvice", score: "4.8", count: "148", href: "#", star: "#f5a623" },
32	  { name: "Google", score: "4.9", count: "205", href: "#", star: "#fbbc05", google: true },
33	];
34	
35	const SOURCE_META: Record<string, { name: string; star: string; google?: boolean; urlKey: string }> = {
36	  TRUSTPILOT: { name: "Trustpilot", star: "#00b67a", urlKey: "review_url_trustpilot" },
37	  HOSTADVICE: { name: "HostAdvice", star: "#f5a623", urlKey: "review_url_hostadvice" },
38	  GOOGLE: { name: "Google", star: "#fbbc05", google: true, urlKey: "review_url_google" },
39	};
40	
41	function Stars({ color }: { color: string }) {
42	  return (
43	    <span style={{ color }} className="text-[13px] leading-none tracking-tight" aria-hidden>
44	      ★★★★★
45	    </span>
46	  );
47	}
48	
49	/** Aggregate approved external reviews into real badges; empty when none qualify. */
50	async function realBadges(): Promise<Badge[]> {
51	  try {
52	    const [grouped, trustpilot, hostadvice, google] = await Promise.all([
53	      db.review.groupBy({
54	        by: ["source"],
55	        where: { approved: true, source: { in: ["TRUSTPILOT", "HOSTADVICE", "GOOGLE"] } },
56	        _avg: { rating: true },
57	        _count: { _all: true },
58	      }),
59	      getSetting("review_url_trustpilot"),
60	      getSetting("review_url_hostadvice"),
61	      getSetting("review_url_google"),
62	    ]);
63	    const urls: Record<string, string> = {
64	      review_url_trustpilot: trustpilot,
65	      review_url_hostadvice: hostadvice,
66	      review_url_google: google,
67	    };
68	
69	    const out: Badge[] = [];
70	    for (const g of grouped) {
71	      const meta = SOURCE_META[g.source];
72	      const count = g._count._all;
73	      const avg = g._avg.rating ?? 0;
74	      const url = meta ? (urls[meta.urlKey] ?? "").trim() : "";
75	      if (!meta || count < 1 || !url) continue; // real data AND somewhere to link
76	      out.push({
77	        name: meta.name,
78	        score: avg.toFixed(1),
79	        count: String(count),
80	        href: url,
81	        star: meta.star,
82	        google: meta.google,
83	      });
84	    }
85	    return out;
86	  } catch {
87	    return [];
88	  }
89	}
90	
91	export async function ReviewBadges() {
92	  const real = await realBadges();
93	  const badges = real.length > 0 ? real : DEMO_BADGES;
94	  const external = real.length > 0;
95	
96	  return (
97	    <div className="flex flex-wrap items-center gap-x-4 gap-y-3">
98	      {badges.map((b) => (
99	        <Link
100	          key={b.name}
101	          href={b.href}
102	          {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
103	          className="group flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.03] px-3 py-1.5 transition-colors hover:border-white/15"
104	          aria-label={`${b.score} out of 5 on ${b.name} — ${b.count} reviews`}
105	        >
106	          <Stars color={b.star} />
107	          <span className="text-xs text-slate-400">
108	            <span className="font-semibold text-white">{b.score}</span> on{" "}
109	            {b.google ? (
110	              <span className="font-semibold">
111	                <span style={{ color: "#4285F4" }}>G</span><span style={{ color: "#EA4335" }}>o</span><span style={{ color: "#FBBC05" }}>o</span><span style={{ color: "#4285F4" }}>g</span><span style={{ color: "#34A853" }}>l</span><span style={{ color: "#EA4335" }}>e</span>
112	              </span>
113	            ) : (
114	              <span className="font-semibold text-slate-300">{b.name}</span>
115	            )}{" "}
116	            <span className="text-slate-500">({b.count})</span>
117	          </span>
118	        </Link>
119	      ))}
120	    </div>
121	  );
122	}
