import { ProductOffersJsonLd, FaqJsonLd, APP_URL } from "@/components/marketing/StructuredData";
import { PLANS } from "@/components/marketing/aihostingtemplate/data";

const PAGE_PATH = "/preview/ai-hosting";
const PAGE_URL = `${APP_URL}${PAGE_PATH}`;

const PRODUCT_NAME = "Nxeon AI App Builder & Hosting";
const PRODUCT_DESCRIPTION =
  "Describe an app in plain English and Claude scaffolds, builds, and deploys it to a real server with HTTPS — you review before anything ships. Or import an app you vibe-coded in Bolt, Lovable, v0, Cursor or Replit and host it on your own Nxeon server with full root.";

// Honest FAQ — every answer matches copy and guardrails on the page itself
// (review-before-deploy gate, real server not a sandbox, no fabricated claims).
const FAQ: { q: string; a: string }[] = [
  {
    q: "How fast does an app go live?",
    a: "In the build flow shown here, a described app is scaffolded, built on a real server, and brought online with HTTPS in about 47 seconds — after you review and approve the plan.",
  },
  {
    q: "Do I review anything before it ships?",
    a: "Yes. Nothing goes live behind your back: Claude shows you the plan and the changes, and only deploys once you approve. It's a review-before-deploy gate, not blind automation.",
  },
  {
    q: "Can I import an app I built in Bolt, Lovable, v0, Cursor or Replit?",
    a: "Yes. Bring the project over and we detect the framework, install dependencies, build it, and put it live on your own Nxeon server with a free HTTPS certificate — no lock-in.",
  },
  {
    q: "Is this real hosting or a sandbox?",
    a: "It runs on a real server, not a throwaway sandbox: full root access, your own database, and always-on monitoring. When you outgrow it you can scale to a full VPS on the same account.",
  },
  {
    q: "Can I use my own domain?",
    a: "Yes. Every plan includes free HTTPS and lets you point a custom domain at your app, alongside the subdomain it ships on.",
  },
];

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps, but
// carries full template-grade metadata and structured data so the direction can
// be evaluated as it would ship.
export const metadata: Metadata = {
  title: "Build with AI, then host it · AI / vibe-coding hosting",
  description: PRODUCT_DESCRIPTION,
  robots: { index: false, follow: false },
  openGraph: {
    title: "Build with AI, then host it — Nxeon",
    description: PRODUCT_DESCRIPTION,
    url: PAGE_URL,
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
    title: "Build with AI, then host it — Nxeon",
    description: PRODUCT_DESCRIPTION,
  },
};

export default function Page() {
  return (
    <>
      <ProductOffersJsonLd
        name={PRODUCT_NAME}
        description={PRODUCT_DESCRIPTION}
        url={PAGE_URL}
        offers={PLANS.map((p) => ({
          name: p.tier,
          price: Number(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />
      <FaqJsonLd items={FAQ} />
      {/* ReviewBadges is an async, DB-backed server component; render two
          instances here and pass them into the client template as slots. */}
      <AIHostingTemplate heroBadges={<ReviewBadges />} reviewsBadges={<ReviewBadges />} />
    </>
  );
}

